import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import { router } from '../src/api/routes.ts';
import { runHandler } from '../src/api/router.ts';
import type { Ctx } from '../src/api/router.ts';

function ctx(over: Partial<Ctx> = {}): Ctx {
  return {
    method: 'GET',
    pathname: '/',
    params: {},
    query: new URLSearchParams(),
    body: undefined,
    userId: 'u-admin',
    userRole: 'LAB_ADMIN',
    ...over,
  };
}

function findHandler(method: string, pattern: string) {
  const route = (router as any).routes.find((r: any) => r.method === method && r.pattern === pattern);
  assert.ok(route, `ไม่พบเส้นทาง ${method} ${pattern}`);
  return route.handler;
}

describe('REQ-52 รูปแบบข้อผิดพลาดเดียวกันทุกกรณี', () => {
  test('GET /resources/:resourceId/availability กับเครื่องที่ไม่มีจริง -> { error: { code, message } }', async () => {
    const handler = findHandler('GET', '/resources/:resourceId/availability');
    const { status, payload } = await runHandler(handler, ctx({ params: { resourceId: 'gpu-h100-99' } }));
    assert.equal(status, 404);
    assert.equal(typeof (payload as any).error.code, 'string');
    assert.equal(typeof (payload as any).error.message, 'string');
  });

  test('GET /billing/invoices ขาด userId/month -> { error: { code, message } }', async () => {
    const handler = findHandler('GET', '/billing/invoices');
    const { status, payload } = await runHandler(handler, ctx({ query: new URLSearchParams() }));
    assert.equal(status, 400);
    assert.equal(typeof (payload as any).error.code, 'string');
    assert.equal(typeof (payload as any).error.message, 'string');
  });
});

